    public Object parseCurrency(Object currency)
    {
        String id = this.safeString(currency, "_coin_id");
        String code = this.safeCurrencyCode(id, (Map<String, Object>) null);
        Map<String, Object> networks = new HashMap<String, Object>() {{}};
        List<Object> chains = (List<Object>) this.safeList(currency, "network_list", new ArrayList<Object>(Arrays.asList()));
        for (var j = 0; j < ((List<?>)chains).size(); j++)
        {
            Object chain = (chains == null || j < 0 || j >= chains.size() ? null : chains.get(j));
            String networkId = this.safeString(chain, "network_id");
            String network = this.networkIdToCode(networkId, code);
            if (!java.util.Objects.equals(network, null))
            {
                networks.put((String)network, Helpers.newMap(
    "info", chain,
    "id", networkId,
    "network", network,
    "active", null,
    "deposit", this.safeBool(chain, "deposit_enabled", false),
    "withdraw", this.safeBool(chain, "withdraw_enabled", false),
    "fee", this.safeNumber(chain, "withdrawal_fee", (Object) null),
    "precision", null,
    "limits", new HashMap<String, Object>() {{
        put( "withdraw", new HashMap<String, Object>() {{
            put( "min", Cryptocom.this.safeNumber(chain, "min_withdrawal_amount", (Object) null) );
            put( "max", null );
        }} );
    }}
));
            }
        }
        return this.safeCurrencyStructure(new HashMap<String, Object>() {{
            put( "info", currency );
            put( "id", id );
            put( "code", code );
            put( "name", Cryptocom.this.safeString(currency, "full_name") );
            put( "active", null );
            put( "deposit", null );
            put( "withdraw", null );
            put( "fee", null );
            put( "precision", null );
            put( "limits", new HashMap<String, Object>() {{
                put( "amount", new HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
            }} );
            put( "type", "crypto" );
            put( "networks", networks );
        }});
    }

